-- rowstile 0.1.0-dev: one_principal. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '5064ee0400d1453c', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '5064ee0400d1453c' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '5064ee0400d1453c' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '5064ee0400d1453c' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM 'a8e8f8e5bfc35f34' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'a8e8f8e5bfc35f34', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'hd_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- A transaction is one principal's: act_as and the logins refuse to sign in someone else (nobody included) once
-- someone is signed in, and to sign in again at all once the transaction views as someone or is limited by scopes
-- (that would end what limits it). Signing in from nobody to someone, and as the same principal again, are fine.
-- Only a sign-in made in this transaction counts (its signature): the policy's owner and superusers say who is
-- signed in by hand, and aren't held to it. rowstile's own functions that ask as others and put back the caller
-- (who, explain, who_among, the invariants) switch without it.
CREATE FUNCTION authz_int.one_principal(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key; v_id text := coalesce(current_setting('authz.user_id', true), '');
        v_type text := coalesce(current_setting('authz.principal_type', true), '');
BEGIN
  IF pg_has_role(session_user, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER') THEN
    RETURN;
  END IF;
  SELECT * INTO k FROM authz_int.session_key;
  -- (compared through their hashes, as session_ok() does)
  IF pg_catalog.sha256(pg_catalog.convert_to(coalesce(current_setting('authz.session', true), ''), 'UTF8'))
     <> pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.concat_ws(pg_catalog.chr(31), coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text), 'UTF8'))), 'hex'), 'UTF8')) THEN
    RETURN;  -- nobody signed in in this transaction yet
  END IF;
  IF coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'this transaction views as user %, so it can''t sign in again', v_id
      USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'a transaction is one principal''s: sign in in a transaction of its own (rowstile help AZ716)';
  END IF;
  IF v_id <> '' AND (v_id, v_type) IS DISTINCT FROM (coalesce(p_id, ''), coalesce(p_type, '')) THEN
    RAISE EXCEPTION 'this transaction is signed in as % already, so it can''t sign in as %',
      CASE WHEN v_type = '' THEN 'user ' || v_id ELSE v_type || ' ' || v_id END,
      CASE WHEN coalesce(p_id, '') = '' THEN 'nobody' WHEN coalesce(p_type, '') = '' THEN 'user ' || p_id
           ELSE p_type || ' ' || p_id END
      USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'a transaction is one principal''s: sign in in a transaction of its own (rowstile help AZ716)';
  END IF;
  IF coalesce(current_setting('authz.scopes', true), '') <> '' THEN
    RAISE EXCEPTION 'this transaction is limited by scopes (%), so it can''t sign in again',
      current_setting('authz.scopes', true) USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'a transaction is one principal''s: sign in in a transaction of its own (rowstile help AZ716)';
  END IF;
END $f$;

-- act_as's work: with p_check, held to one principal a transaction (authz.act_as); without, for rowstile's own
-- functions that sign others in as they ask and put back the caller (who_among)
CREATE FUNCTION authz_int.act_as(p_type text, p_id text, p_check boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id text; v_type text;
BEGIN
  IF p_id IS NOT NULL AND coalesce(p_type, 'user') <> 'user'
     AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = p_type AND principal) THEN
    RAISE EXCEPTION '% is not a type that signs in', p_type USING
      HINT = 'principal types are marked "principal" in the policy: type service = app.services principal (rowstile help AZ707)';
  END IF;
  -- stored as every other id is ('05' is 5), so the audit and created_by name the user as shares do
  v_id := coalesce(authz_int.canon(coalesce(p_type, 'user'), p_id), '');
  v_type := CASE WHEN p_id IS NULL OR coalesce(p_type, 'user') = 'user' THEN '' ELSE p_type END;
  IF p_check THEN
    PERFORM authz_int.one_principal(v_type, v_id);
  END IF;
  PERFORM set_config('authz.user_id', v_id, true);
  PERFORM set_config('authz.principal_type', v_type, true);
  PERFORM set_config('authz.scopes', '', true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
  PERFORM authz_int.jit_off();
END $f$;

-- Which of these people (or principals of another type) hold a permission: who to tell about a change.
-- It signs each one in as act_as does, then the caller again: so only a backend trusted to sign anyone in can
-- use it (the app role), as it could ask authz.can for each one itself. Not in a session limited by scopes or view-as. SELECT * FROM authz.who_among('chat', '7', 'read', ARRAY['1', '2'])
-- (it reads those settings as they are: the guard only keeps its last sign-in, which ends scopes and view-as, from
-- widening the session. Its sign-ins aren't held to one principal a transaction, as authz.act_as's are: it puts
-- back the caller)
CREATE OR REPLACE FUNCTION authz.who_among(p_type text, p_id text, p_perm text, p_users text[], p_principal_type text DEFAULT 'user')
RETURNS SETOF text LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := nullif(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user');
        v_u text;
BEGIN
  -- (it runs as the owner: the caller's own right to sign people in is asked for)
  IF NOT has_function_privilege(authz_int.caller_role(), 'authz.act_as(text, text)', 'EXECUTE') THEN
    RAISE EXCEPTION 'permission denied for function act_as: authz.who_among() signs people in, which % may not',
      authz_int.caller_role() USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF coalesce(current_setting('authz.scopes', true), '') <> '' OR coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'authz.who_among() signs people in, which a session limited by scopes or view-as may not'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  FOREACH v_u IN ARRAY coalesce(p_users, '{}') LOOP
    PERFORM authz_int.act_as(p_principal_type, v_u, false);
    IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_u; END IF;
  END LOOP;
  PERFORM authz_int.act_as(v_pt, v_me, false);
END $f$;

-- Say who is asking, for this transaction: SELECT authz.act_as('user', '42') (NULL, NULL: nobody), first in each
-- transaction. For the app's backend, which signs people in itself; the session is signed, so nothing but this
-- and the logins can change who is signed in. The app role (and its members) may call it.
CREATE OR REPLACE FUNCTION authz.act_as(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM authz_int.act_as(p_type, p_id, true);
END $f$;

-- Sign this transaction out: nobody is signed in in it now, and it may sign in again, as anyone. For a test's
-- transaction, which acts for one person, then another, and is rolled back at the end (the SDKs' test modes do
-- it): outside tests a transaction is one principal's, and work for someone else begins a transaction of its own.
CREATE FUNCTION authz.sign_out() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM set_config('authz.user_id', '', true);
  PERFORM set_config('authz.principal_type', '', true);
  PERFORM set_config('authz.scopes', '', true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
END $f$;

-- Sign in with an API key for this transaction: SELECT authz.login_key('ak_...'). Returns who:
-- a user's id, or type:id for another principal
CREATE OR REPLACE FUNCTION authz.login_key(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz.api_keys;
BEGIN
  SELECT * INTO k FROM authz.api_keys WHERE hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex');
  IF k.id IS NULL OR k.revoked_at IS NOT NULL OR (k.expires_at IS NOT NULL AND k.expires_at <= now()) THEN
    RAISE EXCEPTION 'invalid API key' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  PERFORM authz_int.one_principal(CASE WHEN k.principal_type = 'user' THEN '' ELSE k.principal_type END, k.user_id);
  PERFORM set_config('authz.user_id', k.user_id, true);
  PERFORM set_config('authz.principal_type', CASE WHEN k.principal_type = 'user' THEN '' ELSE k.principal_type END, true);
  PERFORM set_config('authz.scopes', k.scopes, true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'invalid API key' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  -- when it was last used, to the minute: never waiting on another request with the key (the row they
  -- lock), and not at all in a read-only transaction (a replica, a GET)
  IF pg_catalog.current_setting('transaction_read_only') = 'off' THEN
    UPDATE authz.api_keys SET last_used_at = now()
    WHERE id = (SELECT x.id FROM authz.api_keys x
                WHERE x.id = k.id AND (x.last_used_at IS NULL OR x.last_used_at < now() - interval '1 minute')
                FOR UPDATE SKIP LOCKED);
  END IF;
  PERFORM authz_int.jit_off();
  RETURN authz_int.actor();
END $f$;

-- Sign in with a JWT (HS256) for this transaction: SELECT authz.login_jwt('eyJ...')
-- Settings (authz.settings): jwt_secret (required), jwt_issuer, jwt_audience, jwt_user_claim (default sub),
-- jwt_type_claim (a claim naming the principal's type, for services; absent or 'user': a user).
-- Tokens must carry exp.
-- A 'scope' claim (space separated) limits the transaction to those policy scopes.
CREATE OR REPLACE FUNCTION authz.login_jwt(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE parts text[] := string_to_array(coalesce(p_token, ''), '.'); v_head jsonb; v_claims jsonb; v_secret text;
        v_user text; v_type text; v_scopes text[]; v_now numeric := extract(epoch FROM now()); v_want text;
BEGIN
  SELECT value INTO v_secret FROM authz.settings WHERE key = 'jwt_secret';
  IF v_secret IS NULL THEN RAISE EXCEPTION 'JWT login is not configured (authz.settings jwt_secret)' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703'; END IF;
  BEGIN
    IF cardinality(parts) <> 3 THEN RAISE EXCEPTION 'bad'; END IF;
    v_head := convert_from(authz_int.b64url(parts[1]), 'UTF8')::jsonb;
    v_claims := convert_from(authz_int.b64url(parts[2]), 'UTF8')::jsonb;
    -- the signatures compared through their hashes: the time it takes says nothing of how much of the token's is right
    IF v_head->>'alg' IS DISTINCT FROM 'HS256'
       OR sha256(authz_int.b64url(parts[3]))
          IS DISTINCT FROM sha256(authz_int.hmac_sha256(convert_to(v_secret, 'UTF8'),
                                                        convert_to(parts[1] || '.' || parts[2], 'UTF8'))) THEN
      RAISE EXCEPTION 'bad';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END;
  -- an expiry is required; both are numbers of seconds
  IF jsonb_typeof(v_claims->'exp') IS DISTINCT FROM 'number' OR (v_claims->>'exp')::numeric <= v_now
     OR (v_claims ? 'nbf' AND (jsonb_typeof(v_claims->'nbf') <> 'number' OR (v_claims->>'nbf')::numeric > v_now)) THEN
    RAISE EXCEPTION 'token expired or not yet valid' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_issuer';
  IF v_want IS NOT NULL AND v_claims->>'iss' IS DISTINCT FROM v_want THEN
    RAISE EXCEPTION 'token from another issuer' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_audience';
  -- (coalesce: without the claim both sides are NULL, and a token that names no audience is not for this one)
  IF v_want IS NOT NULL AND NOT coalesce(v_claims->>'aud' = v_want
       OR (jsonb_typeof(v_claims->'aud') = 'array' AND v_claims->'aud' ? v_want), false) THEN
    RAISE EXCEPTION 'token for another audience' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  v_user := v_claims->>coalesce((SELECT value FROM authz.settings WHERE key = 'jwt_user_claim'), 'sub');
  v_type := v_claims->>(SELECT value FROM authz.settings WHERE key = 'jwt_type_claim');
  IF coalesce(v_type, 'user') <> 'user' AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = v_type AND principal) THEN
    RAISE EXCEPTION 'the token names a type that does not sign in' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  v_user := coalesce(authz_int.canon(coalesce(v_type, 'user'), v_user), '');
  v_type := CASE WHEN coalesce(v_type, 'user') = 'user' THEN '' ELSE v_type END;
  PERFORM authz_int.one_principal(v_type, v_user);
  PERFORM set_config('authz.user_id', v_user, true);
  PERFORM set_config('authz.principal_type', v_type, true);
  PERFORM set_config('authz.acting_user', '', true);
  IF v_claims ? 'scope' THEN
    v_scopes := ARRAY(SELECT x FROM unnest(string_to_array(v_claims->>'scope', ' ')) x
                      WHERE EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x));
    PERFORM set_config('authz.scopes', CASE WHEN cardinality(v_scopes) = 0 THEN '(none)'
                                            ELSE array_to_string(v_scopes, ',') END, true);
  ELSE
    PERFORM set_config('authz.scopes', '', true);
  END IF;
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'the token names no active user' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  PERFORM authz_int.jit_off();
  RETURN authz_int.actor();
END $f$;

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('"hd_app"');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'hd_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'hd_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'hd_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- the policy's owner (or a member of it): its sessions are believed unsigned, it may read rowstile's tables
  -- (the session key among them) and turn row-level security off (applying refuses it, AZ624: this finds a grant made since)
  FOR r IN SELECT n.nspowner::regrole AS owner FROM pg_namespace n, pg_roles a
           WHERE n.nspname = 'authz_int' AND a.oid = v_role AND NOT a.rolsuper AND pg_has_role(v_role, n.nspowner, 'MEMBER') LOOP
    severity := 'error'; object := 'hd_app';
    problem := format('is the policy''s owner %s, or a member of it: who is signed in is believed without a signature, and it may read rowstile''s tables and turn row-level security off. The app role must be a role of its own: not the tables'' owner or the policy''s, nor a member of either', r.owner);
    RETURN NEXT;
  END LOOP;
  -- rowstile's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND a.privilege_type = 'SELECT'
